export const Default: Story = {
  name: "Default",
  play: async ({ canvasElement }) => {
    const host = canvasElement.querySelector('ds-input')!;
    // The native "input" event is composed: it reaches listeners on the element.
    const onInput = fn();
    host.addEventListener('input', onInput);
    const field = within(shadowOf(canvasElement, 'ds-input') as unknown as HTMLElement).getByLabelText("Label");
    await userEvent.type(field, 'Hello');
    await expect(field).toHaveValue('Hello');
    await expect(host.value).toBe('Hello');
    await expect(onInput).toHaveBeenCalledTimes(5);
    await expect(field).toHaveAccessibleDescription("We'll never share this.");
  },
};

