/** The clear button empties the input and keeps focus in it. */
export const Clear: Story = {
  name: "Clear",
  tags: ['!dev'],
  args: { clearable: true },
  play: async ({ canvasElement }) => {
    const host = canvasElement.querySelector('ds-input')!;
    host.value = 'Hello';
    await host.updateComplete;
    const shadow = within(shadowOf(canvasElement, 'ds-input') as unknown as HTMLElement);
    await userEvent.click(shadow.getByRole('button', { name: 'Clear' }));
    await expect(shadow.getByRole('textbox')).toHaveValue('');
    await expect(host.value).toBe('');
    await expect(shadowOf(canvasElement, 'ds-input').activeElement).toBe(shadow.getByRole('textbox'));
  },
};

